// int → Integer (오토박싱: 자동 변환)
List<Integer> list = new ArrayList<>();
list.add(5);          // 오토박싱: int → Integer
int n = list.get(0);  // 언박싱: Integer → int

// 함정: Integer 비교할 때
Integer a = 200;
Integer b = 200;
a == b;  // false — 128 이상은 캐싱 안 됨
a.equals(b);  // true — 내용 비교

