title:
// Generic 없으면 — 마구 넣고 빼담 때 타입 캐스팅 필요
List list = new ArrayList();
list.add("hello");
list.add(123);              // 다른 타입 섞어도 컴파일 통과
String s = (String) list.get(1); // 런타임 ClassCastException

// Generic 사용
List<String> list = new ArrayList<>();
list.add("hello");
list.add(123); // ❌ 컴파일 에러 — 런타임 전에 잡힌
String s = list.get(0);   // 타입 캐스팅 불필요

